parameters.inputSchema:
={{ (() => {
  const record = {
    type: 'object',
    properties: {
      id:             { type: 'string' },
      llm_reason:     { type: 'string' },
      source_type:    { type: 'string', enum: ['ciudadano', 'medio', 'institucional', 'otro'] },
      sentiment_llm:  { type: ['string', 'null'], enum: ['POS', 'NEG', 'NEU', null] },
      has_irony:      { type: 'boolean' },
      mixed:          { type: 'boolean' },
      lang:           { type: ['string', 'null'], enum: ['es', 'jopara', null] },
      discarded:      { type: 'boolean' },
      discard_reason: { type: ['string', 'null'], enum: ['guarani', 'ininteligible', null] }
    },
    required: ['id', 'llm_reason', 'source_type', 'sentiment_llm', 'has_irony', 'mixed', 'lang', 'discarded', 'discard_reason'],
    additionalProperties: false
  };
  return JSON.stringify({ type: 'array', items: record });
})() }}

parameters.jsCode:
const topic = $('Get available').first().json;

return [
  {
    json: {
      id: topic.id,
      empty_streak: topic.empty_streak,
      topic_id: topic.topic_id,
      name: topic.name,
      page: topic.page,
      items: [],
    },
  },
];

const llmItems = $input.all();
const topic = $('Get available').first().json;

// output puede venir como array directo o envuelto en classifications
const out = llmItems.find(
  ({ json }) => Array.isArray(json.output) || Array.isArray(json.output?.classifications),
)?.json.output;
const classifications = Array.isArray(out) ? out : out?.classifications;

if (!classifications) {
  throw new Error('No se encontraron las clasificaciones');
}

const originalItems = Object.values($('Scrapper').first().json.items ?? {});
const originalById = new Map(originalItems.map((item) => [String(item.id), item]));

const SENTIMENTS = ['POS', 'NEG', 'NEU'];
const SOURCE_TYPES = ['ciudadano', 'medio', 'institucional', 'otro'];
const LANGS = ['es', 'jopara'];
const DISCARD_REASONS = ['guarani', 'ininteligible'];

const classifiedIds = new Set();
const classifiedAt = new Date().toISOString();

const classifiedItems = classifications.map((c) => {
  const identifier = String(c.id);
  const original = originalById.get(identifier);
  if (!original) {
    throw new Error(`No se encontró la publicación con ID ${identifier}`);
  }
  if (classifiedIds.has(identifier)) {
    throw new Error(`ID repetido en la clasificación: ${identifier}`);
  }

  if (typeof c.discarded !== 'boolean') {
    throw new Error(`discarded inválido para el ID ${identifier}`);
  }
  if (typeof c.has_irony !== 'boolean' || typeof c.mixed !== 'boolean') {
    throw new Error(`has_irony/mixed inválidos para el ID ${identifier}`);
  }
  if (!SOURCE_TYPES.includes(c.source_type)) {
    throw new Error(`source_type inválido para el ID ${identifier}: ${c.source_type}`);
  }

  if (c.discarded) {
    if (c.sentiment_llm !== null) throw new Error(`Descartado con sentiment_llm no nulo: ${identifier}`);
    if (c.lang !== null) throw new Error(`Descartado con lang no nulo: ${identifier}`);
    if (!DISCARD_REASONS.includes(c.discard_reason)) {
      throw new Error(`discard_reason inválido para el ID ${identifier}: ${c.discard_reason}`);
    }
  } else {
    if (!SENTIMENTS.includes(c.sentiment_llm)) {
      throw new Error(`Sentimiento inválido para el ID ${identifier}: ${c.sentiment_llm}`);
    }
    if (c.discard_reason !== null) {
      throw new Error(`discard_reason debe ser null si no está descartado: ${identifier}`);
    }
    if (!LANGS.includes(c.lang)) {
      throw new Error(`lang inválido para el ID ${identifier}: ${c.lang}`);
    }
  }

  classifiedIds.add(identifier);
  const { id: _, ...publication } = original;
  return {
    ...publication,
    identifier,
    sentiment_llm: c.sentiment_llm,
    source_type: c.source_type,
    lang: c.lang,
    has_irony: c.has_irony,
    mixed: c.mixed,
    discarded: c.discarded,
    discard_reason: c.discard_reason,
    llm_reason: c.llm_reason,
    llm_model: $env.MODEL,
    llm_prompt_version: '4',
    llm_classified_at: classifiedAt,
  };
});

// Los que NO volvieron = omitidos por otro país (esperado, no es error)
const omittedIds = [...originalById.keys()].filter((id) => !classifiedIds.has(id));

return [
  {
    json: {
      id: topic.id,
      empty_streak: topic.empty_streak,
      topic_id: topic.topic_id,
      name: topic.name,
      page: topic.page,
      items: classifiedItems,
      omitted_other_country: { count: omittedIds.length, ids: omittedIds },
    },
  },
];
